import React, { useState, useEffect } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, Cell } from 'recharts';
import { Calculator, AlertTriangle, Info } from 'lucide-react';

const RecoupmentCalculator: React.FC = () => {
  const [advance, setAdvance] = useState<number>(200000);
  const [royaltyRate, setRoyaltyRate] = useState<number>(15);
  const [grossNeeded, setGrossNeeded] = useState<number>(0);

  useEffect(() => {
    // Formula: Advance / (Royalty Rate / 100)
    const rateDecimal = royaltyRate / 100;
    const required = rateDecimal > 0 ? advance / rateDecimal : 0;
    setGrossNeeded(required);
  }, [advance, royaltyRate]);

  const labelShare = grossNeeded - advance;

  const data = [
    {
      name: 'Revenue Split',
      Artist: advance,
      Label: labelShare,
      Total: grossNeeded,
    },
  ];

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);
  };

  return (
    <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200">
      <div className="flex items-center gap-2 mb-6">
        <div className="p-2 bg-indigo-100 rounded-lg text-indigo-700">
          <Calculator size={24} />
        </div>
        <h2 className="text-xl font-bold text-slate-800">The Recoupment Trap Calculator</h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div className="bg-slate-50 p-4 rounded-lg text-sm text-slate-600 border border-slate-200">
            <div className="flex gap-2 items-start">
              <Info className="w-5 h-5 text-indigo-500 shrink-0 mt-0.5" />
              <p>
                <strong>The Math:</strong> If you take a <strong>{formatCurrency(advance)}</strong> advance at a <strong>{royaltyRate}%</strong> royalty rate, 
                you do not break even when the song earns {formatCurrency(advance)}. 
                You only break even when <em>your share</em> (15%) equals the advance.
              </p>
            </div>
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">
              Advance Amount ($)
            </label>
            <input
              type="number"
              value={advance}
              onChange={(e) => setAdvance(Number(e.target.value))}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
              min="0"
              step="5000"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-slate-700 mb-1">
              Royalty Rate (%)
            </label>
            <input
              type="number"
              value={royaltyRate}
              onChange={(e) => setRoyaltyRate(Number(e.target.value))}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none"
              min="1"
              max="100"
            />
          </div>

          <div className="pt-4 border-t border-slate-100">
             <h3 className="text-sm uppercase tracking-wide text-slate-500 font-semibold mb-2">Required Gross Sales</h3>
             <div className="text-3xl font-bold text-red-600 font-mono">
               {formatCurrency(grossNeeded)}
             </div>
             <p className="text-xs text-slate-500 mt-1">
               The song must generate this much before you earn your first royalty dollar beyond the advance.
             </p>
          </div>
        </div>

        <div className="min-h-[300px] flex flex-col">
          <h3 className="text-sm font-medium text-slate-700 mb-4 text-center">Where the Money Goes</h3>
          <div className="flex-1 w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={data}
                margin={{ top: 20, right: 30, left: 20, bottom: 5 }}
              >
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" hide />
                <YAxis tickFormatter={(val) => `$${val / 1000}k`} />
                <Tooltip 
                  formatter={(value: number) => formatCurrency(value)}
                  cursor={{fill: 'transparent'}}
                />
                <Legend />
                <Bar dataKey="Artist" stackId="a" fill="#4f46e5" name="Paid to Artist (Advance)" radius={[0, 0, 4, 4]} />
                <Bar dataKey="Label" stackId="a" fill="#cbd5e1" name="Kept by Label" radius={[4, 4, 0, 0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-4 flex gap-2 items-center justify-center text-xs text-amber-700 bg-amber-50 p-2 rounded border border-amber-100">
            <AlertTriangle size={14} />
            <span>The label keeps <strong>{formatCurrency(labelShare)}</strong> while you pay back your own loan.</span>
          </div>
        </div>
      </div>
    </div>
  );
};

export default RecoupmentCalculator;

import React from 'react';
import { Phase } from '../types';
import { Hammer, TrendingUp, Briefcase } from 'lucide-react';

interface PhaseCardProps {
  phase: Phase;
}

const PhaseCard: React.FC<PhaseCardProps> = ({ phase }) => {
  const getIcon = () => {
    switch (phase.id) {
      case 'builder': return <Hammer className="text-emerald-500" size={32} />;
      case 'buzzer': return <TrendingUp className="text-amber-500" size={32} />;
      case 'professional': return <Briefcase className="text-indigo-500" size={32} />;
      default: return null;
    }
  };

  const getBorderColor = () => {
    switch (phase.id) {
      case 'builder': return 'border-emerald-200';
      case 'buzzer': return 'border-amber-200';
      case 'professional': return 'border-indigo-200';
      default: return 'border-slate-200';
    }
  };

  return (
    <div className={`bg-white p-6 rounded-xl shadow-sm border-2 ${getBorderColor()} hover:shadow-md transition-shadow`}>
      <div className="flex items-center gap-3 mb-4">
        <div className="p-3 bg-slate-50 rounded-full border border-slate-100">
          {getIcon()}
        </div>
        <h3 className="text-lg font-bold text-slate-900">{phase.title}</h3>
      </div>

      <div className="space-y-4">
        <div>
          <h4 className="text-xs font-bold uppercase text-slate-400 mb-1">Description</h4>
          <p className="text-slate-700 text-sm leading-relaxed">{phase.description}</p>
        </div>

        <div className="bg-slate-50 p-3 rounded-lg border border-slate-100">
          <h4 className="text-xs font-bold uppercase text-slate-500 mb-1">The Reality</h4>
          <p className="text-slate-800 text-sm italic">"{phase.reality}"</p>
        </div>
      </div>
    </div>
  );
};

export default PhaseCard;

import React, { useState } from 'react';
import { Choice } from '../types';
import { CheckCircle2, XCircle, Scale } from 'lucide-react';

interface ChoiceExplorerProps {
  choices: Choice[];
}

const ChoiceExplorer: React.FC<ChoiceExplorerProps> = ({ choices }) => {
  const [activeChoiceId, setActiveChoiceId] = useState<string>(choices[0].id);

  const activeChoice = choices.find(c => c.id === activeChoiceId) || choices[0];

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
      <div className="bg-slate-900 text-white p-6">
        <div className="flex items-center gap-3 mb-2">
          <Scale className="text-amber-400" />
          <h2 className="text-2xl font-bold">Critical Decisions Matrix</h2>
        </div>
        <p className="text-slate-300">Navigate the high-stakes choices that define your ownership and wealth.</p>
      </div>

      <div className="flex border-b border-slate-200 overflow-x-auto">
        {choices.map((choice) => (
          <button
            key={choice.id}
            onClick={() => setActiveChoiceId(choice.id)}
            className={`px-6 py-4 text-sm font-medium whitespace-nowrap transition-colors ${
              activeChoiceId === choice.id
                ? 'bg-white text-indigo-600 border-b-2 border-indigo-600'
                : 'bg-slate-50 text-slate-600 hover:bg-slate-100'
            }`}
          >
            {choice.title}
          </button>
        ))}
      </div>

      <div className="p-6 md:p-8">
        <div className="mb-8">
          <h3 className="text-xl font-bold text-slate-800 mb-2">{activeChoice.title}</h3>
          <p className="text-slate-600">{activeChoice.description}</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {activeChoice.options.map((option, idx) => (
            <div key={idx} className="flex flex-col h-full border border-slate-200 rounded-xl overflow-hidden hover:border-indigo-300 transition-colors">
              <div className="bg-slate-50 p-4 border-b border-slate-200">
                <h4 className="font-bold text-lg text-slate-900">{option.title}</h4>
                <p className="text-sm text-slate-500 mt-1">{option.description}</p>
              </div>

              <div className="p-5 flex-1 space-y-4">
                <div className="flex gap-3 items-start">
                  <CheckCircle2 className="w-5 h-5 text-emerald-500 shrink-0 mt-0.5" />
                  <div>
                    <span className="block text-xs font-bold text-emerald-700 uppercase mb-1">Benefit</span>
                    <p className="text-sm text-slate-700">{option.consequences.positive}</p>
                  </div>
                </div>

                <div className="flex gap-3 items-start">
                  <XCircle className="w-5 h-5 text-rose-500 shrink-0 mt-0.5" />
                  <div>
                    <span className="block text-xs font-bold text-rose-700 uppercase mb-1">Risk</span>
                    <p className="text-sm text-slate-700">{option.consequences.negative}</p>
                  </div>
                </div>

                {option.mathExample && (
                  <div className="mt-4 p-3 bg-amber-50 rounded border border-amber-100 text-xs text-amber-800">
                    <strong>The Math:</strong> {option.mathExample}
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default ChoiceExplorer;

