interface ImpactSimulatorProps {
  sectors: SectorData[];
}

const ImpactSimulator: React.FC<ImpactSimulatorProps> = ({ sectors }) => {
  const [selectedSectorId, setSelectedSectorId] = useState<string>("");
  const [directJobs, setDirectJobs] = useState(50);

  // Set default sector when sectors load
  useEffect(() => {
    if (sectors.length > 0 && !selectedSectorId) {
      setSelectedSectorId(sectors[0].id);
    }
  }, [sectors]);

  const sector = sectors.find(s => s.id === selectedSectorId) || sectors[0] || {
    id: 'unknown',
    name: 'Loading...',
    multiplier: 1,
    jobsMultiplier: 0,
    leakageScore: 'Low',
    description: '',
    opportunity: ''
  };

  // Simple Impact Calculation Logic
  const indirectJobs = Math.round(directJobs * sector.jobsMultiplier);
  const totalJobs = directJobs + indirectJobs;
  const totalEconomicActivity = directJobs * 65000 * sector.multiplier; // Assuming $65k avg output per job for simplicity

  const chartData = [
    {
      name: 'Job Creation',
      Direct: directJobs,
      'Indirect/Induced': indirectJobs,
    }
  ];

  const formatCurrency = (val: number) => {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(val);
  };

  if (!sectors.length) return <div>Loading Simulator...</div>;

  return (
    <div className="bg-white p-6 rounded-xl shadow-lg border border-slate-200">
      <div className="flex items-center gap-3 mb-6 pb-4 border-b border-slate-100">
        <div className="p-2 bg-indigo-100 rounded-lg text-indigo-700">
          <Calculator size={24} />
        </div>
        <div>
          <h2 className="text-xl font-bold text-slate-800">Community Wealth Simulator</h2>
          <p className="text-sm text-slate-500">Model the "Multiplier Effect" of Black-led ventures.</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="space-y-6">
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-2">
              1. Choose a Sector to Expand
            </label>
            <select 
              className="w-full p-3 border border-slate-300 rounded-lg bg-slate-50 focus:ring-2 focus:ring-indigo-500 outline-none"
              value={selectedSectorId}
              onChange={(e) => setSelectedSectorId(e.target.value)}
            >
              {sectors.map(s => (
                <option key={s.id} value={s.id}>{s.name} (Multiplier: {s.multiplier}x)</option>
              ))}
            </select>
            <p className="text-xs text-slate-500 mt-2 italic">
              {sector.description}
            </p>
          </div>

          <div>
            <label className="block text-sm font-bold text-slate-700 mb-2">
              2. Number of New Jobs Created
            </label>
            <div className="flex items-center gap-4">
              <input
                type="range"
                min="10"
                max="500"
                step="10"
                value={directJobs}
                onChange={(e) => setDirectJobs(Number(e.target.value))}
                className="flex-1 h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
              />
              <span className="w-16 text-center font-mono font-bold text-lg border p-1 rounded bg-slate-50">
                {directJobs}
              </span>
            </div>
          </div>

          <div className="bg-indigo-50 p-4 rounded-lg border border-indigo-100">
            <h3 className="text-xs font-bold uppercase text-indigo-800 mb-2 flex items-center gap-2">
              <Layers size={14} /> Structural Insight
            </h3>
            <p className="text-sm text-indigo-900 leading-relaxed">
              <strong>Opportunity Area:</strong> {sector.opportunity}
            </p>
          </div>
        </div>

        {/* Output Visualization */}
        <div className="bg-slate-50 p-4 rounded-xl border border-slate-200 flex flex-col justify-between">
          <div className="mb-4">
             <h3 className="text-sm font-bold text-slate-600 mb-2 text-center">Projected Job Impact</h3>
             <div className="h-48">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={chartData} layout="vertical">
                    <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                    <XAxis type="number" hide />
                    <YAxis dataKey="name" type="category" hide />
                    <Tooltip cursor={{fill: 'transparent'}} />
                    <Legend />
                    <Bar dataKey="Direct" stackId="a" fill="#4f46e5" radius={[4, 0, 0, 4]} />
                    <Bar dataKey="Indirect/Induced" stackId="a" fill="#10b981" radius={[0, 4, 4, 0]} name="Multiplier Jobs" />
                  </BarChart>
                </ResponsiveContainer>
             </div>
