import React from 'react';
import { SectorData } from '../types';
import { TrendingUp, ArrowUpRight, ArrowDownRight, Droplets, Info } from 'lucide-react';

interface SectorOpportunitiesProps {
  sectors: SectorData[];
}

const SectorOpportunities: React.FC<SectorOpportunitiesProps> = ({ sectors }) => {

  const formatCompactCurrency = (number: number) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      notation: "compact",
      maximumFractionDigits: 1
    }).format(number);
  };

  return (
    <div className="bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
      <div className="bg-slate-900 text-white p-6">
        <div className="flex items-center gap-3 mb-2">
          <TrendingUp className="text-emerald-400" />
          <h2 className="text-xl font-bold">Sector Supply Chain Matrix</h2>
        </div>
        <p className="text-slate-300 text-sm">Identifying where regional demand is "leaking" out due to high import dependencies.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 divide-y md:divide-y-0 md:divide-x divide-slate-200">
        {sectors.map((sector) => {
          const leakageAmount = sector.regionalDemand * (sector.netLeakagePct / 100);
          const retentionPct = 100 - sector.netLeakagePct;

          return (
            <div key={sector.id} className="p-6 hover:bg-slate-50 transition-colors flex flex-col h-full">
               <div className="flex justify-between items-start mb-4">
                  <h3 className="font-bold text-slate-800 leading-tight h-10 pr-2">{sector.name}</h3>
                  <div className="flex flex-col items-end">
                      <span className="text-[10px] text-slate-400 font-bold uppercase tracking-wide">Multiplier</span>
                      <span className="text-sm font-mono font-bold text-emerald-600">{sector.multiplier}x</span>
                  </div>
               </div>

               {/* Leakage Visualizer */}
               <div className="mb-4">
                  <div className="flex justify-between text-xs mb-1">
                      <span className="font-bold text-slate-600">Regional Retention</span>
                      <span className="font-bold text-red-600">Leakage</span>
                  </div>
                  <div className="w-full h-3 bg-slate-200 rounded-full overflow-hidden flex">
                      <div className="h-full bg-emerald-500" style={{ width: `${retentionPct}%` }}></div>
                      <div className="h-full bg-red-400" style={{ width: `${sector.netLeakagePct}%` }}></div>
                  </div>
                  <div className="flex justify-between text-[10px] text-slate-500 mt-1">
                      <span>{retentionPct}% Captured</span>
                      <span>{sector.netLeakagePct}% Leaks</span>
                  </div>
               </div>

               {/* Quantitative Metrics */}
               <div className="grid grid-cols-2 gap-2 mb-4">
                  <div className="bg-red-50 p-2 rounded border border-red-100">
                      <div className="flex items-center gap-1 text-[10px] text-red-600 uppercase font-bold mb-0.5">
                          <Droplets size={10} />
                          Lost Revenue
                      </div>
                      <div className="text-sm font-bold text-slate-900">
                          {formatCompactCurrency(leakageAmount)}
                      </div>
                  </div>
                  <div className="bg-slate-100 p-2 rounded border border-slate-200 relative group cursor-help">
                      <div className="flex items-center gap-1 text-[10px] text-slate-500 uppercase font-bold mb-0.5">
                          Import Coeff.
                          <Info size={10} />
                      </div>
                      <div className="text-sm font-bold text-slate-900">
                          {sector.importDependency}%
                      </div>
                      {/* Tooltip for Import Coeff */}
                      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-32 bg-slate-800 text-white text-[10px] p-2 rounded hidden group-hover:block z-10 shadow-lg pointer-events-none">
                          {sector.importDependency}% of intermediate inputs are imported.
                      </div>
                  </div>
               </div>

               <div className="mt-auto">
                   <div>
                      <span className="text-xs text-slate-400 uppercase tracking-wider font-semibold">SMA Action Insight</span>
                      <div className="mt-2 p-3 bg-indigo-50 rounded border border-indigo-100 text-sm text-indigo-900">
                          {sector.opportunity}
                      </div>
                   </div>
               </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

