import EquityDashboard from './components/EquityDashboard';
import SectorOpportunities from './components/SectorOpportunities';
import LaborMarketAnalysis from './components/LaborMarketAnalysis';
import CapitalBarriers from './components/CapitalBarriers';
import DataStatus from './components/DataStatus';
import { Menu, X, ChevronDown, MapPin, Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [activeTab, setActiveTab] = useState<'overview' | 'equity' | 'simulator'>('overview');

  // Data State
  const [regionId, setRegionId] = useState<string>('memphis');
  const [data, setData] = useState<RegionDataBundle | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const availableRegions = EconomicDataService.getAvailableRegions();

  // Async Fetch Effect
  useEffect(() => {
    let mounted = true;

    const fetchData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        const result = await EconomicDataService.fetchRegionData(regionId);
        if (mounted) {
          setData(result);
          setIsLoading(false);
        }
      } catch (err) {
        if (mounted) {
          setError("Failed to connect to regional data streams.");
          setIsLoading(false);
        }
      }
    };

    fetchData();

    return () => { mounted = false; };
  }, [regionId]);

  const handleRegionChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setRegionId(e.target.value);
  };

  return (
    <div className="min-h-screen bg-slate-50 text-slate-900 font-sans">

      {/* Live Data Status Bar */}
      <DataStatus 
        isLoading={isLoading} 
        lastUpdated={data?.lastUpdated || null} 
        regionName={data?.context.name || "Unknown"} 
      />

      {/* Header */}
      <header className="sticky top-0 z-50 bg-slate-900 text-white border-b border-slate-800 shadow-lg">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center gap-4">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 bg-gradient-to-br from-amber-400 to-amber-600 rounded flex items-center justify-center font-bold text-slate-900 text-xs shadow-inner">
                  SMA
                </div>
                <div className="flex flex-col">
                  <span className="font-bold text-base leading-none">Economic Equity Dashboard</span>
                </div>
              </div>

              {/* Region Selector */}
              <div className="hidden md:flex items-center ml-4 bg-slate-800 rounded-md border border-slate-700 px-3 py-1">
                <MapPin size={14} className="text-slate-400 mr-2" />
                <select 
                  value={regionId} 
                  onChange={handleRegionChange}
                  className="bg-transparent text-sm text-white focus:outline-none cursor-pointer"
                  disabled={isLoading}
                >
                  {availableRegions.map(r => (
                    <option key={r.id} value={r.id} className="bg-slate-800">{r.name}</option>
                  ))}
                </select>
                <ChevronDown size={14} className="text-slate-400 ml-2" />
              </div>
            </div>

            {/* Desktop Nav */}
            <nav className="hidden md:flex gap-1">
              <button 
                onClick={() => setActiveTab('overview')}
                className={`px-3 py-2 text-sm font-medium rounded-md transition-colors ${
                    activeTab === 'overview' ? 'bg-slate-800 text-amber-400' : 'text-slate-300 hover:text-white hover:bg-slate-800'
                }`}
              >
                Regional Pulse
              </button>
              <button 
                onClick={() => setActiveTab('equity')}
                className={`px-3 py-2 text-sm font-medium rounded-md transition-colors ${
                    activeTab === 'equity' ? 'bg-slate-800 text-amber-400' : 'text-slate-300 hover:text-white hover:bg-slate-800'
                }`}
              >
                Equity Gaps
              </button>
              <button 
                onClick={() => setActiveTab('simulator')}
                className={`px-3 py-2 text-sm font-medium rounded-md transition-colors ${
                    activeTab === 'simulator' ? 'bg-slate-800 text-amber-400' : 'text-slate-300 hover:text-white hover:bg-slate-800'
                }`}
              >
                Impact Simulator
              </button>
            </nav>

            {/* Mobile Menu Button */}
            <button 
              className="md:hidden p-2 text-slate-300 hover:text-white"
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            >
              {mobileMenuOpen ? <X /> : <Menu />}
            </button>
          </div>
        </div>

        {/* Mobile Nav */}
        {mobileMenuOpen && (
          <div className="md:hidden bg-slate-800 border-t border-slate-700">
             <div className="px-4 py-3 border-b border-slate-700">
                <label className="text-xs text-slate-400 block mb-1">Select Region</label>
                <select 
                  value={regionId} 
                  onChange={handleRegionChange}
                  className="w-full bg-slate-900 text-white p-2 rounded border border-slate-600"
                >
                  {availableRegions.map(r => (
                    <option key={r.id} value={r.id}>{r.name}</option>
                  ))}
                </select>
             </div>
             <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
                <button onClick={() => { setActiveTab('overview'); setMobileMenuOpen(false); }} className="block w-full text-left px-3 py-2 text-white">Regional Pulse</button>
                <button onClick={() => { setActiveTab('equity'); setMobileMenuOpen(false); }} className="block w-full text-left px-3 py-2 text-white">Equity Gaps</button>
                <button onClick={() => { setActiveTab('simulator'); setMobileMenuOpen(false); }} className="block w-full text-left px-3 py-2 text-white">Impact Simulator</button>
             </div>
          </div>
        )}
      </header>

      {/* Main Content */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">

        {/* Loading State */}
        {isLoading && (
            <div className="flex flex-col items-center justify-center py-20 animate-fade-in">
                <Loader2 size={40} className="text-indigo-600 animate-spin mb-4" />
                <h3 className="text-lg font-medium text-slate-600">Syncing with Federal Databases...</h3>
                <p className="text-sm text-slate-400">Fetching latest census and BLS employment figures for {availableRegions.find(r => r.id === regionId)?.name}.</p>
            </div>
        )}

        {/* Error State */}
        {!isLoading && error && (
            <div className="bg-red-50 border border-red-200 text-red-700 p-6 rounded-lg text-center">
                <p>{error}</p>
                <button onClick={() => window.location.reload()} className="underline mt-2">Retry Connection</button>
            </div>
        )}

        {/* Data View */}
        {!isLoading && !error && data && (
            <div className="space-y-8 animate-fade-in">

                {activeTab === 'overview' && (
                    <div className="space-y-8">
                        {/* Hero Stats */}
                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            {data.indicators.map((indicator) => (
                                <div key={indicator.id} className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm hover:shadow-md transition-shadow">
                                    <h3 className="text-sm font-medium text-slate-500 mb-2">{indicator.label}</h3>
                                    <div className="flex items-end gap-3 mb-2">
                                        <span className="text-3xl font-bold text-slate-900">{indicator.value}</span>
                                        <span className={`text-xs font-bold px-2 py-1 rounded mb-1 ${
                                            indicator.trend === 'up' ? 'bg-red-100 text-red-700' : 
                                            indicator.trend === 'down' ? 'bg-emerald-100 text-emerald-700' : 'bg-slate-100 text-slate-700'
                                        }`}>
                                            {indicator.trendLabel}
                                        </span>
                                    </div>
                                    <p className="text-xs text-slate-400 border-t border-slate-100 pt-2 mt-2">{indicator.context}</p>
                                </div>
                            ))}
                        </div>

                        {/* Labor Market Deep Dive */}
                        <LaborMarketAnalysis stats={data.laborStats} regionName={data.context.name} />

                        <SectorOpportunities sectors={data.sectors} />

                        <div className="bg-indigo-900 rounded-xl p-8 text-white flex flex-col md:flex-row items-center gap-6 shadow-xl">
                            <div className="flex-1">
                                <h2 className="text-2xl font-bold mb-2">Why This Matters</h2>
                                <p className="text-indigo-200 text-lg leading-relaxed">
                                    "The goal isn't just to increase black employment—it's to capture the multiplier effect. When we own the supply chain, the dollar circulates within our community instead of leaking out."
                                </p>
                            </div>
                            <div className="shrink-0">
                                 <button 
                                    onClick={() => setActiveTab('simulator')}
                                    className="bg-amber-400 text-slate-900 hover:bg-amber-300 px-6 py-3 rounded-lg font-bold transition-colors shadow-lg"
                                 >
                                    Run Impact Simulation
                                 </button>
                            </div>
                        </div>
                    </div>
                )}

                {activeTab === 'equity' && (
                    <div className="space-y-8">
                         <div className="bg-white p-6 rounded-xl border border-slate-200">
                            <h2 className="text-lg font-bold text-slate-800 mb-2">Structural Analysis: {data.context.name}</h2>
                            <p className="text-slate-600 max-w-3xl">
                                These charts visualize the "starting line" disparity in {data.context.state}. Policy interventions that ignore these wealth and capital gaps will fail to produce equitable outcomes. SMA focuses on <strong>Asset-Building</strong> rather than just income.
                            </p>
                         </div>
                        <EquityDashboard data={data.gaps} />
                        {/* DEEP DIVE: Capital Barriers */}
                        <CapitalBarriers data={data.capitalMetrics} />
                    </div>
                )}

                {activeTab === 'simulator' && (
                    <div className="space-y-8">
                        <ImpactSimulator sectors={data.sectors} />
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="bg-white p-6 rounded-xl border border-slate-200">
                                <h3 className="font-bold text-slate-800 mb-2">For Policymakers</h3>
                                <p className="text-sm text-slate-600">
                                    Use this data to justify procurement set-asides. If a project uses "Green Construction," require local hiring to trigger the 1.85x multiplier shown above.
                                </p>
                            </div>
                            <div className="bg-white p-6 rounded-xl border border-slate-200">
                                 <h3 className="font-bold text-slate-800 mb-2">For Philanthropy</h3>
                                 <p className="text-sm text-slate-600">
                                    Stop funding "training" without demand. Fund the <strong>Business Owners</strong> in the high-multiplier sectors so they can afford to hire the trainees.
                                 </p>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        )}
      </main>
    </div>
  );
};

export default App;

payload.text:
**Focusing Geographic Granularity**

I'm thinking about how to make the dashboard more specific geographically. Right now, it's just showing data for metros like Memphis and Atlanta. I need to figure out how to add a higher level of detail, taking into account the "Metro Delta Region" as a starting point. It's a key factor.


**Mapping Disparities Now**

I've been drilling down on the geographic granularity issue. It's clear that metro-level data is too broad; we need census tract or county-level views to pinpoint hotspots effectively for targeted interventions. I'm updating the app architecture now to accommodate this. Because of the mock backend I have to simulate this structure, but it will be a valid demonstration. I'm updating `types.ts` to include a `Hotspot` and updating the region bundle, and will then update `constants.ts` and build a component to visualize it.


**Visualizing Sub-Regions**

I'm now focusing on how to visualize the hotspot data. A grid of cards or a heatmap is likely the best approach, but I'll avoid heavy map dependencies. I'll build a "Hotspot Analysis" view to compare sub-regions side-by-side to highlight the neighborhood gap. I'm updating `App.tsx` and adding a new section within "Regional Pulse" for "Neighborhood Drill-down". I'm thinking of a toggle between "Metro Average" and "Neighborhood Hotspots" views.


**Defining Geographic Hotspots**

I'm now revising the 'Neighborhood Drill-down' section. After thinking about user clarity, I'm leaning toward a "Geographic Disparity" section within the 'Overview' for now, using a `GeographicHotspots` component. I'm focusing on defining the data structure for hotspots, including name, type, key metrics, and risk level, and updating `types.ts` accordingly. I will modify it as follows:

```typescript
export interface GeographicHotspot {
  id: string;
  name: string;
  type: 'Neighborhood' | 'County' | 'Census Tract';
  population: number;
  unemploymentRate: number;
  povertyRate: number;
  medianIncome: number;
  riskLevel: 'Critical' | 'High' | 'Moderate' | 'Low';
}
```


**Incorporating Sub-Regions**

I'm now integrating sub-regional data. I've added a `hotspots` array to `RegionDataBundle` in `types.ts` and populated mock hotspots in `constants.ts` for Memphis, Birmingham, and Atlanta, including distinct neighborhoods with varying poverty levels and demographics. The core component, `components/GeographicDrilldown.tsx`, is under construction. It will feature a table/card grid displaying these hotspots, coupled with bar charts to compare them with the metro average, and an insightful text summary. The next step is connecting this to the main app flow.


**Constructing the "Heatmap"**

I'm now deep in the code, building the `GeographicDrilldown` component. The design is solidifying as a heatmap-style table, clearly showing "The Local Reality". It'll display neighborhood names, unemployment and income comparisons against the metro average, and a status indicator. I'm focusing on the component structure, including the header and table rows, and updating `types.ts` to include 'Census Tract' in the hotspot type. I'm also preparing to integrate this component into `App.tsx` and review existing components.


**Building the Integration**

I'm now integrating the `GeographicDrilldown` component into the `App.tsx` structure. My focus is ensuring the "Neighborhood-Level Granularity" view seamlessly fits within the existing 'Overview' section. I've updated `types.ts` to include the `homeOwnershipRate` and `riskScore` for a richer picture, as well. Updating `constants.ts` with the new data structure, and then finally updating `App.tsx` to render the component.


**Augmenting Actionability**

I'm now enhancing the `GeographicDrilldown` component. The `GeographicHotspot` type will include an `interventionTarget` field. I'll display comparison bars for unemployment and add a risk level badge to each hotspot, and add a "Targeting Recommendation" for each. I am updating `types.ts` and will add the corresponding visuals in the component.

